using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

// Register the chat client via MEAI abstraction
var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient()));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteTools = host.Services.GetRequiredService<NoteTools>();

// Build the agent with tools
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Description = "An agent that researches topics by searching the web and taking notes, then summarizes findings.",
    Instructions = """
        You are a research assistant. When given a topic:
        1. Use the web_search tool to find relevant information (perform multiple searches with different queries).
        2. Use the save_note tool to record key findings as you go.
        3. Use the get_notes tool to review what you have collected.
        4. After gathering enough information, provide a comprehensive summary of your findings.
        Be thorough — search from multiple angles and note the most important facts.
        """,
};

// Determine the research topic
var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest advances in quantum computing in 2026";

Console.WriteLine($"🔍 Researching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = [
        AIFunctionFactory.Create(ResearchTools.WebSearch),
        AIFunctionFactory.Create(noteTools.SaveNote),
        AIFunctionFactory.Create(noteTools.GetNotes),
    ],
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n✅ Research complete.");

// --- Tool definitions ---

public sealed class ResearchTools
{
    [Description("Search the web for information on a given query. Returns a list of relevant search result snippets.")]
    public static IReadOnlyList<string> WebSearch(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (e.g., Bing Search, Google Custom Search).
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        return
        [
            $"[Result 1 for '{query}'] — Comprehensive overview article discussing key developments and current state of research.",
            $"[Result 2 for '{query}'] — Recent academic paper highlighting breakthroughs and future directions.",
            $"[Result 3 for '{query}'] — Industry analysis covering practical applications and market impact.",
        ];
    }
}

public sealed class NoteTools
{
    private readonly List<string> _notes = [];

    [Description("Save a research note capturing a key finding or piece of information.")]
    public string SaveNote(
        [Description("The note content to save")] string content)
    {
        _notes.Add(content);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes collected so far.")]
    public IReadOnlyList<string> GetNotes()
    {
        Console.WriteLine($"  📋 Reviewing {_notes.Count} note(s)");
        return _notes.AsReadOnly();
    }
}

