    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Create the chat client via MEAI abstraction
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

var noteTools = new NoteTools();

// Build the agent with web search and note-taking tools
var tools = new List<AITool>
{
    AIFunctionFactory.Create(ResearchTools.WebSearch),
    AIFunctionFactory.Create(noteTools.SaveNote),
    AIFunctionFactory.Create(noteTools.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes, then summarizes findings.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the web_search tool to find relevant information (perform multiple searches with different queries).
        2. Use the save_note tool to record key findings as you go.
        3. Use the get_notes tool to review what you have collected.
        4. After gathering enough information, provide a comprehensive summary of your findings.
        Be thorough — search from multiple angles and note the most important facts.
        """,
    tools: tools);

// Determine the research topic
var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest advances in quantum computing in 2026";

Console.WriteLine($"🔍 Researching: {topic}\n");

var session = await agent.CreateSessionAsync();

await foreach (var update in agent.RunStreamingAsync(
    $"Research the following topic and provide a summary: {topic}",
    session))
{
    if (!string.IsNullOrEmpty(update.Text))
    {
        Console.Write(update.Text);
    }
}

Console.WriteLine("\n\n✅ Research complete.");

